import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Cache the product data with 'products' tag
const getCachedProducts = unstable_cache(
  async () => {
    return getAllProducts();
  },
  ['products'],
  {
    tags: ['products']
  }
);

// Server action to invalidate the products cache
export async function invalidateProductsCache() {
  'use server';

  // Use revalidateTag to invalidate the cache
  revalidateTag('products');
}

// Product Listing Component
async function ProductList() {
  const products = await getCachedProducts();

  return (
    <div className="space-y-4">
      <h2 className="text-2xl font-bold">Products</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {products.map((product) => (
          <div key={product.id} className="border p-4 rounded-lg">
            <h3 className="font-semibold">{product.name}</h3>
            <p className="text-gray-600">${product.price}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default async function Page() {
  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-6">Product Listing with Cache Invalidation</h1>

      {/* Product List with Caching */}
      <ProductList />

      {/* Cache Invalidation Form */}
      <div className="mt-8 p-4 border rounded-lg">
        <h2 className="text-xl font-semibold mb-4">Cache Management</h2>
        <form action={invalidateProductsCache}>
          <p className="mb-4 text-sm text-gray-600">
            Invalidate the products cache to refresh data from the database.
          </p>
          <button
            type="submit"
            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition-colors"
          >
            Invalidate Products Cache
          </button>
        </form>
      </div>
    </div>
  );
}

